def _ledger(priority, tax_base, refunds):
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            revision = event.get("revision", 0)
            key = ((revision, position) if priority == "revision_first"
                   else (sequence, revision, position))
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            base = raw if tax_base == "original" else net
            tax = rounded(base * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if refunds and event.get("kind") == "refund":
                total = -total
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _dependency_resolver():
    from itertools import product

    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]

        domains = {}
        for name in names:
            versions = [row["version"] for row in packages[name]
                        if row["version"] not in blocked.get(name, [])
                        and (name not in pins or row["version"] == pins[name])]
            domains[name] = versions

        best_vector = None
        best = None
        choices = [domains[name] + [None] for name in names]
        for values in product(*choices):
            assignment = dict(zip(names, values))
            installed = {name for name, version in assignment.items()
                         if version is not None}
            if any(name not in installed or
                   not low <= assignment[name] <= high
                   for name, (low, high) in roots.items()):
                continue

            edges = {name: [] for name in installed}
            closure = set()
            stack = list(roots)
            valid = True
            while stack and valid:
                name = stack.pop()
                if name in closure:
                    continue
                closure.add(name)
                version = assignment.get(name)
                if version is None:
                    valid = False
                    break
                row = next((r for r in packages[name]
                            if r["version"] == version), None)
                if row is None:
                    valid = False
                    break
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    other_version = assignment.get(other)
                    if (other_version is None or
                            not dep["min"] <= other_version <= dep["max"]):
                        valid = False
                        break
                    edges[name].append(other)
                    if other not in closure:
                        stack.append(other)
            if not valid or closure != installed:
                continue

            active, finished = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                for other in edges[name]:
                    if not visit(other):
                        return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in installed):
                continue

            vector = tuple(assignment[name] if assignment[name] is not None else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = {name: assignment[name] for name in names
                        if assignment[name] is not None}

        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}
    return solve


def _quota_intervals():
    from itertools import combinations

    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        best_value = None
        best_ids = None

        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            points = {job["start"] for job in subset}
            points.update(job["end"] for job in subset)
            if any(sum(job["start"] <= point < job["end"]
                       for job in subset) > 2 for point in points):
                continue

            value = sum(job["value"] for job in subset)
            selected = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and selected > best_ids)):
                best_value, best_ids = value, selected

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _temporal_routes():
    import heapq

    def solve(data):
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        required = data.get("required", [])
        bits = {node: 1 << index for index, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source, target = data["source"], data["target"]
        start = data["start"]
        coupons = data["coupons"]
        initial_mask = bits.get(source, 0)
        initial = (source, initial_mask, coupons)
        distance = {initial: start}
        queue = [(start, source, initial_mask, coupons)]

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distance.get(state) != time:
                continue
            if node == target and mask == full:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                duration = edge["duration"]
                options = [(duration, remaining)]
                if remaining:
                    discounted = max(1, duration - edge.get("discount", 0))
                    options.append((discounted, remaining - 1))
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                for travel, left in options:
                    arrival = depart + travel
                    if arrival > data["deadline"]:
                        continue
                    next_state = (next_node, next_mask, left)
                    if arrival < distance.get(next_state, float("inf")):
                        distance[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, left))
        return {"arrival": None}
    return solve


